#!/usr/bin/env bash
# Runs the "Sync Device Types" job for every manufacturer folder in device-types/ (one run each).
# Generated from the device-types/ folders; regenerate when manufacturers are added.
#
# Requires NAUTOBOT_URL and NAUTOBOT_TOKEN in the environment.
# Can be run from any directory: it changes to the folder that contains the repository.

set -u
cd "$(dirname "$0")/../.." || exit 1

: "${NAUTOBOT_URL:?set NAUTOBOT_URL}"
: "${NAUTOBOT_TOKEN:?set NAUTOBOT_TOKEN}"

FAILED=()

python3 nautobot_devicetype_library/scripts/nautobot_sync.py --insecure -m '3Com' --commit --debug -v device || FAILED+=('3Com')
